namespace JunexisLang.Compiler.CodeGen;

using JunexisLang.Compiler.Core;
using JunexisLang.Compiler.IR;

internal static class StorageRuntimeClientGenerator
{
    internal static GeneratedFile? Generate(IRDocument ir)
    {
        if (!StorageRuntimeContractGenerator.HasServerStorage(ir))
            return null;

        return new GeneratedFile(
            "server",
            "server/junexis/storage/runtime/client.go",
            GeneratedGoSource.Render(Source));
    }

    private const string Source = """
        // Code generated by Junexis. DO NOT EDIT.
        // Package runtime connects a generated Go backend to Storage Runtime ABI 0.1.
        package runtime

        import (
            "bufio"
            "bytes"
            "context"
            "encoding/json"
            "errors"
            "fmt"
            "io"
            "os"
            "os/exec"
            "strings"
            "sync"
            "time"

            junexisStorage "junexis/server/junexis/storage"
        )

        const abiVersion = "junexis.storage.runtime/0.1"

        // Config identifies one provider process and one deployment binding.
        type Config struct {
            HostPath          string
            ProviderEntrypoint string
            ProviderID        string
            BindingID         string
            Values            map[string]string
            OperationTimeout  time.Duration
        }

        // Provider implements junexis.storage/0.1 over the process ABI.
        type Provider struct {
            mu       sync.Mutex
            command  *exec.Cmd
            stdin    io.WriteCloser
            scanner  *bufio.Scanner
            stderr   bytes.Buffer
            binding  string
            timeout  time.Duration
            nextID   uint64
            closed   bool
        }

        type request struct {
            SchemaVersion string            `json:"schemaVersion"`
            RequestID     string            `json:"requestId"`
            Action        string            `json:"action"`
            SupportedABI  []string          `json:"supportedAbi,omitempty"`
            ProviderID    string            `json:"providerId,omitempty"`
            BindingID     string            `json:"bindingId,omitempty"`
            Config        map[string]string `json:"config,omitempty"`
            Operation     string            `json:"operation,omitempty"`
            Effect        string            `json:"effect,omitempty"`
            Input         any               `json:"input,omitempty"`
            TransactionID string            `json:"transactionId,omitempty"`
            CursorID      string            `json:"cursorId,omitempty"`
            TimeoutMS     int64             `json:"timeoutMs,omitempty"`
        }

        type response struct {
            SchemaVersion string          `json:"schemaVersion"`
            RequestID     string          `json:"requestId"`
            Success       bool            `json:"success"`
            Result        json.RawMessage `json:"result"`
            Error         *responseError  `json:"error"`
        }

        type responseError struct {
            ErrorClass string `json:"errorClass"`
            Code       string `json:"code"`
            Message    string `json:"message"`
        }

        type invokeResult struct {
            Mode     string          `json:"mode"`
            Value    json.RawMessage `json:"value"`
            CursorID string          `json:"cursorId"`
        }

        type recordValue struct {
            Key     string          `json:"key"`
            Payload json.RawMessage `json:"payload"`
        }

        type cursorStep struct {
            Done bool            `json:"done"`
            Item json.RawMessage `json:"item"`
        }

        type transactionResult struct {
            TransactionID string `json:"transactionId"`
        }

        // MutationResult is the confirmed, provider-neutral result of mutation.plan.
        type MutationResult struct {
            SchemaVersion string `json:"schemaVersion"`
            Outcome       string `json:"outcome"`
            AffectedRows  int64  `json:"affectedRows"`
        }

        type remoteTransaction struct {
            provider *Provider
            id       string
        }

        var _ junexisStorage.Store = (*Provider)(nil)

        // OpenFromEnvironment resolves the generic runtime binding selected by deployment.
        func OpenFromEnvironment(ctx context.Context) (*Provider, *junexisStorage.Error) {
            values := map[string]string{}
            if encoded := strings.TrimSpace(os.Getenv("JUNEXIS_STORAGE_CONFIG_JSON")); encoded != "" {
                if err := json.Unmarshal([]byte(encoded), &values); err != nil {
                    return nil, storageError("open", junexisStorage.ErrorConstraint, false, "known", errors.New("invalid storage config"))
                }
            }
            timeout := 5 * time.Second
            return Open(ctx, Config{
                HostPath:           strings.TrimSpace(os.Getenv("JUNEXIS_STORAGE_RUNTIME_HOST")),
                ProviderEntrypoint: strings.TrimSpace(os.Getenv("JUNEXIS_STORAGE_PROVIDER_ENTRYPOINT")),
                ProviderID:         strings.TrimSpace(os.Getenv("JUNEXIS_STORAGE_PROVIDER")),
                BindingID:          strings.TrimSpace(os.Getenv("JUNEXIS_STORAGE_BINDING")),
                Values:             values,
                OperationTimeout:   timeout,
            })
        }

        // Open starts one explicitly selected host and provider package.
        func Open(ctx context.Context, config Config) (*Provider, *junexisStorage.Error) {
            if err := ctx.Err(); err != nil {
                return nil, contextError("open", err)
            }
            if config.HostPath == "" || config.ProviderEntrypoint == "" || config.ProviderID == "" {
                return nil, storageError("open", junexisStorage.ErrorConstraint, false, "known", errors.New("runtime binding is incomplete"))
            }
            if config.BindingID == "" {
                config.BindingID = "default"
            }
            if config.OperationTimeout <= 0 {
                config.OperationTimeout = 5 * time.Second
            }

            args := []string{"--provider", config.ProviderEntrypoint}
            var command *exec.Cmd
            if strings.EqualFold(strings.ToLower(filepathExtension(config.HostPath)), ".dll") {
                command = exec.Command("dotnet", append([]string{config.HostPath}, args...)...)
            } else {
                command = exec.Command(config.HostPath, args...)
            }
            stdin, err := command.StdinPipe()
            if err != nil {
                return nil, storageError("open", junexisStorage.ErrorUnavailable, true, "known", err)
            }
            stdout, err := command.StdoutPipe()
            if err != nil {
                _ = stdin.Close()
                return nil, storageError("open", junexisStorage.ErrorUnavailable, true, "known", err)
            }
            provider := &Provider{
                command: command,
                stdin: stdin,
                scanner: bufio.NewScanner(stdout),
                binding: config.BindingID,
                timeout: config.OperationTimeout,
            }
            provider.scanner.Buffer(make([]byte, 64*1024), 16*1024*1024)
            command.Stderr = &provider.stderr
            if err := command.Start(); err != nil {
                _ = stdin.Close()
                return nil, storageError("open", junexisStorage.ErrorUnavailable, true, "known", err)
            }

            provider.mu.Lock()
            defer provider.mu.Unlock()
            if _, storageErr := provider.roundTripLocked(ctx, request{
                Action: "handshake", SupportedABI: []string{abiVersion},
            }); storageErr != nil {
                provider.terminateLocked()
                return nil, storageErr
            }
            if _, storageErr := provider.roundTripLocked(ctx, request{
                Action: "open", ProviderID: config.ProviderID, BindingID: config.BindingID, Config: config.Values,
            }); storageErr != nil {
                provider.terminateLocked()
                return nil, storageErr
            }
            return provider, nil
        }

        // Put stores one canonical JSON payload.
        func (p *Provider) Put(ctx context.Context, bucket string, key string, payload []byte) *junexisStorage.Error {
            if !json.Valid(payload) {
                return storageError("put", junexisStorage.ErrorConstraint, false, "known", errors.New("payload is not JSON"))
            }
            p.mu.Lock()
            defer p.mu.Unlock()
            _, storageErr := p.invokeLocked(ctx, "put", "write", map[string]any{
                "bucket": bucket, "key": key, "payload": json.RawMessage(payload),
            }, "")
            return storageErr
        }

        // Get reads one record by bucket and key.
        func (p *Provider) Get(ctx context.Context, bucket string, key string) (junexisStorage.Record, *junexisStorage.Error) {
            p.mu.Lock()
            defer p.mu.Unlock()
            return p.getLocked(ctx, bucket, key, "")
        }

        // List reads a sequential result to completion.
        func (p *Provider) List(ctx context.Context, bucket string) ([]junexisStorage.Record, *junexisStorage.Error) {
            p.mu.Lock()
            defer p.mu.Unlock()
            return p.listLocked(ctx, bucket, "")
        }

        // Delete removes one record idempotently.
        func (p *Provider) Delete(ctx context.Context, bucket string, key string) *junexisStorage.Error {
            p.mu.Lock()
            defer p.mu.Unlock()
            _, storageErr := p.invokeLocked(ctx, "delete", "delete", map[string]any{
                "bucket": bucket, "key": key,
            }, "")
            return storageErr
        }

        // QueryPlan executes one compiler-generated, provider-neutral read plan.
        func (p *Provider) QueryPlan(ctx context.Context, input any) ([]json.RawMessage, *junexisStorage.Error) {
            p.mu.Lock()
            defer p.mu.Unlock()
            result, storageErr := p.invokeEnvelopeLocked(ctx, "query.plan", "read", input, "")
            if storageErr != nil {
                return nil, storageErr
            }
            if result.Mode != "sequence" || result.CursorID == "" {
                return nil, storageError("query.plan", junexisStorage.ErrorInternal, false, "known", errors.New("provider did not return a query sequence"))
            }
            rows := []json.RawMessage{}
            for {
                raw, nextErr := p.roundTripLocked(ctx, request{
                    Action: "next", BindingID: p.binding, CursorID: result.CursorID,
                })
                if nextErr != nil {
                    p.cancelCursorLocked(result.CursorID)
                    return nil, nextErr
                }
                var step cursorStep
                if err := json.Unmarshal(raw, &step); err != nil {
                    p.cancelCursorLocked(result.CursorID)
                    return nil, storageError("query.plan", junexisStorage.ErrorInternal, false, "known", err)
                }
                if step.Done {
                    return rows, nil
                }
                rows = append(rows, append(json.RawMessage(nil), step.Item...))
            }
        }

        // MutationPlan executes one compiler-generated, provider-neutral write plan.
        func (p *Provider) MutationPlan(ctx context.Context, input any) (MutationResult, *junexisStorage.Error) {
            p.mu.Lock()
            defer p.mu.Unlock()
            result, storageErr := p.invokeEnvelopeLocked(ctx, "mutation.plan", "write", input, "")
            if storageErr != nil {
                return MutationResult{}, storageErr
            }
            if result.Mode != "value" || len(result.Value) == 0 {
                return MutationResult{}, storageError("mutation.plan", junexisStorage.ErrorInternal, false, "known", errors.New("provider did not return a mutation value"))
            }
            var mutation MutationResult
            if err := json.Unmarshal(result.Value, &mutation); err != nil {
                return MutationResult{}, storageError("mutation.plan", junexisStorage.ErrorInternal, false, "known", err)
            }
            if mutation.SchemaVersion != "junexis.storage.mutation-result/0.1" || mutation.AffectedRows < 0 ||
                (mutation.Outcome == "applied" && mutation.AffectedRows == 0) ||
                (mutation.Outcome == "not-applied" && mutation.AffectedRows != 0) ||
                (mutation.Outcome != "applied" && mutation.Outcome != "not-applied") {
                return MutationResult{}, storageError("mutation.plan", junexisStorage.ErrorInternal, false, "known", errors.New("provider returned an invalid mutation result"))
            }
            return mutation, nil
        }

        // Transact runs work inside one explicit provider transaction.
        func (p *Provider) Transact(ctx context.Context, work junexisStorage.TransactionWork) *junexisStorage.Error {
            p.mu.Lock()
            defer p.mu.Unlock()
            result, storageErr := p.roundTripLocked(ctx, request{Action: "begin", BindingID: p.binding})
            if storageErr != nil {
                return storageErr
            }
            var begun transactionResult
            if err := json.Unmarshal(result, &begun); err != nil || begun.TransactionID == "" {
                return storageError("begin", junexisStorage.ErrorInternal, false, "known", err)
            }
            transaction := &remoteTransaction{provider: p, id: begun.TransactionID}
            if workErr := work(transaction); workErr != nil {
                _, rollbackErr := p.roundTripLocked(ctx, request{
                    Action: "rollback", BindingID: p.binding, TransactionID: begun.TransactionID,
                })
                if rollbackErr != nil {
                    return rollbackErr
                }
                return workErr
            }
            _, storageErr = p.roundTripLocked(ctx, request{
                Action: "commit", BindingID: p.binding, TransactionID: begun.TransactionID,
            })
            return storageErr
        }

        // Health checks readiness through the host ABI.
        func (p *Provider) Health(ctx context.Context) *junexisStorage.Error {
            p.mu.Lock()
            defer p.mu.Unlock()
            _, storageErr := p.roundTripLocked(ctx, request{Action: "health", BindingID: p.binding})
            return storageErr
        }

        // Close closes the binding and stops its owned host process.
        func (p *Provider) Close() *junexisStorage.Error {
            p.mu.Lock()
            defer p.mu.Unlock()
            if p.closed {
                return nil
            }
            _, closeErr := p.roundTripLocked(context.Background(), request{Action: "close", BindingID: p.binding})
            _, shutdownErr := p.roundTripLocked(context.Background(), request{Action: "shutdown"})
            p.closed = true
            _ = p.stdin.Close()
            waitErr := p.command.Wait()
            if closeErr != nil {
                return closeErr
            }
            if shutdownErr != nil {
                return shutdownErr
            }
            if waitErr != nil {
                return storageError("close", junexisStorage.ErrorUnavailable, true, "known", waitErr)
            }
            return nil
        }

        func (t *remoteTransaction) Put(ctx context.Context, bucket string, key string, payload []byte) *junexisStorage.Error {
            if !json.Valid(payload) {
                return storageError("put", junexisStorage.ErrorConstraint, false, "known", errors.New("payload is not JSON"))
            }
            _, storageErr := t.provider.invokeLocked(ctx, "put", "write", map[string]any{
                "bucket": bucket, "key": key, "payload": json.RawMessage(payload),
            }, t.id)
            return storageErr
        }

        func (t *remoteTransaction) Get(ctx context.Context, bucket string, key string) (junexisStorage.Record, *junexisStorage.Error) {
            return t.provider.getLocked(ctx, bucket, key, t.id)
        }

        func (t *remoteTransaction) List(ctx context.Context, bucket string) ([]junexisStorage.Record, *junexisStorage.Error) {
            return t.provider.listLocked(ctx, bucket, t.id)
        }

        func (t *remoteTransaction) Delete(ctx context.Context, bucket string, key string) *junexisStorage.Error {
            _, storageErr := t.provider.invokeLocked(ctx, "delete", "delete", map[string]any{
                "bucket": bucket, "key": key,
            }, t.id)
            return storageErr
        }

        func (p *Provider) getLocked(ctx context.Context, bucket string, key string, transactionID string) (junexisStorage.Record, *junexisStorage.Error) {
            result, storageErr := p.invokeLocked(ctx, "get", "read", map[string]any{
                "bucket": bucket, "key": key,
            }, transactionID)
            if storageErr != nil {
                return junexisStorage.Record{}, storageErr
            }
            var value recordValue
            if err := json.Unmarshal(result, &value); err != nil {
                return junexisStorage.Record{}, storageError("get", junexisStorage.ErrorInternal, false, "known", err)
            }
            return junexisStorage.Record{Key: value.Key, Payload: append([]byte(nil), value.Payload...)}, nil
        }

        func (p *Provider) listLocked(ctx context.Context, bucket string, transactionID string) ([]junexisStorage.Record, *junexisStorage.Error) {
            result, storageErr := p.invokeEnvelopeLocked(ctx, "list", "read", map[string]any{"bucket": bucket}, transactionID)
            if storageErr != nil {
                return nil, storageErr
            }
            if result.Mode != "sequence" || result.CursorID == "" {
                return nil, storageError("list", junexisStorage.ErrorInternal, false, "known", errors.New("provider did not return a sequence"))
            }
            records := []junexisStorage.Record{}
            for {
                raw, nextErr := p.roundTripLocked(ctx, request{
                    Action: "next", BindingID: p.binding, CursorID: result.CursorID,
                })
                if nextErr != nil {
                    _, _ = p.roundTripLocked(context.Background(), request{
                        Action: "cancel-sequence", BindingID: p.binding, CursorID: result.CursorID,
                    })
                    return nil, nextErr
                }
                var step cursorStep
                if err := json.Unmarshal(raw, &step); err != nil {
                    p.cancelCursorLocked(result.CursorID)
                    return nil, storageError("list", junexisStorage.ErrorInternal, false, "known", err)
                }
                if step.Done {
                    return records, nil
                }
                var value recordValue
                if err := json.Unmarshal(step.Item, &value); err != nil {
                    p.cancelCursorLocked(result.CursorID)
                    return nil, storageError("list", junexisStorage.ErrorInternal, false, "known", err)
                }
                records = append(records, junexisStorage.Record{
                    Key: value.Key, Payload: append([]byte(nil), value.Payload...),
                })
            }
        }

        func (p *Provider) invokeLocked(ctx context.Context, operation string, effect string, input any, transactionID string) (json.RawMessage, *junexisStorage.Error) {
            result, storageErr := p.invokeEnvelopeLocked(ctx, operation, effect, input, transactionID)
            if storageErr != nil {
                return nil, storageErr
            }
            if result.Mode != "value" {
                return nil, storageError(operation, junexisStorage.ErrorInternal, false, "known", errors.New("provider did not return a value"))
            }
            return result.Value, nil
        }

        func (p *Provider) invokeEnvelopeLocked(ctx context.Context, operation string, effect string, input any, transactionID string) (invokeResult, *junexisStorage.Error) {
            raw, storageErr := p.roundTripLocked(ctx, request{
                Action: "invoke", BindingID: p.binding, Operation: operation, Effect: effect,
                Input: input, TransactionID: transactionID,
            })
            if storageErr != nil {
                return invokeResult{}, storageErr
            }
            var result invokeResult
            if err := json.Unmarshal(raw, &result); err != nil {
                return invokeResult{}, storageError(operation, junexisStorage.ErrorInternal, false, "known", err)
            }
            return result, nil
        }

        func (p *Provider) roundTripLocked(ctx context.Context, message request) (json.RawMessage, *junexisStorage.Error) {
            if p.closed {
                return nil, storageError(message.Action, junexisStorage.ErrorUnavailable, true, "known", errors.New("provider is closed"))
            }
            if err := ctx.Err(); err != nil {
                return nil, contextError(message.Action, err)
            }
            p.nextID++
            message.SchemaVersion = abiVersion
            message.RequestID = fmt.Sprintf("go-%d", p.nextID)
            timeout := p.timeout
            if deadline, ok := ctx.Deadline(); ok {
                remaining := time.Until(deadline)
                if remaining < timeout {
                    timeout = remaining
                }
            }
            if timeout <= 0 {
                return nil, contextError(message.Action, context.DeadlineExceeded)
            }
            message.TimeoutMS = timeout.Milliseconds()
            encoded, err := json.Marshal(message)
            if err != nil {
                return nil, storageError(message.Action, junexisStorage.ErrorInternal, false, "known", err)
            }
            if _, err := p.stdin.Write(append(encoded, '\n')); err != nil {
                return nil, storageError(message.Action, junexisStorage.ErrorUnavailable, true, "known", err)
            }
            if !p.scanner.Scan() {
                return nil, storageError(message.Action, junexisStorage.ErrorUnavailable, true, "unknown", p.scanner.Err())
            }
            var reply response
            if err := json.Unmarshal(p.scanner.Bytes(), &reply); err != nil {
                return nil, storageError(message.Action, junexisStorage.ErrorInternal, false, "known", err)
            }
            if reply.SchemaVersion != abiVersion || reply.RequestID != message.RequestID {
                return nil, storageError(message.Action, junexisStorage.ErrorInternal, false, "unknown", errors.New("storage runtime response correlation failed"))
            }
            if !reply.Success {
                code := junexisStorage.ErrorInternal
                cause := errors.New("storage runtime rejected operation")
                if reply.Error != nil {
                    code = junexisStorage.ErrorCode(reply.Error.ErrorClass)
                    if reply.Error.Message != "" {
                        cause = errors.New(reply.Error.Message)
                    }
                }
                return nil, storageError(message.Action, code, retryable(code), outcome(code), cause)
            }
            return reply.Result, nil
        }

        func (p *Provider) cancelCursorLocked(cursorID string) {
            _, _ = p.roundTripLocked(context.Background(), request{
                Action: "cancel-sequence", BindingID: p.binding, CursorID: cursorID,
            })
        }

        func (p *Provider) terminateLocked() {
            p.closed = true
            _ = p.stdin.Close()
            if p.command.Process != nil {
                _ = p.command.Process.Kill()
            }
            _ = p.command.Wait()
        }

        func storageError(operation string, code junexisStorage.ErrorCode, retryableValue bool, outcomeValue string, cause error) *junexisStorage.Error {
            return &junexisStorage.Error{Code: code, Operation: operation, Retryable: retryableValue, Outcome: outcomeValue, Cause: cause}
        }

        func contextError(operation string, err error) *junexisStorage.Error {
            if errors.Is(err, context.DeadlineExceeded) {
                return storageError(operation, junexisStorage.ErrorTimeout, true, "known", err)
            }
            return storageError(operation, junexisStorage.ErrorCancelled, true, "known", err)
        }

        func retryable(code junexisStorage.ErrorCode) bool {
            return code == junexisStorage.ErrorBusy || code == junexisStorage.ErrorTimeout ||
                code == junexisStorage.ErrorCancelled || code == junexisStorage.ErrorUnavailable
        }

        func outcome(code junexisStorage.ErrorCode) string {
            if code == junexisStorage.ErrorUnknownOutcome {
                return "unknown"
            }
            return "known"
        }

        func filepathExtension(path string) string {
            slash := strings.LastIndexAny(path, "/\\")
            dot := strings.LastIndex(path, ".")
            if dot <= slash {
                return ""
            }
            return path[dot:]
        }
        """;
}
